const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>Number(v).toLocaleString('ko-KR')+'원';
const carrierNames=['CJ대한통운','한진택배','롯데택배','우체국택배','로젠택배'];
let goods=JSON.parse(localStorage.goodsProducts||'null')||[{id:1,name:'말마 인형',description:'귀여운 말마 캐릭터 봉제 인형',price:29000,stock:18,status:'sale',art:'MALMA'},{id:2,name:'경주마 인형 A',price:26000,stock:9,status:'sale',art:'RACE A'},{id:3,name:'경주마 인형 B',price:26000,stock:0,status:'soldout',art:'RACE B'}];
let settings={shippingFee:3000,cancelHours:24,shippingNotice:'주 1회 모아서 발송합니다. 주간 마감과 발송일은 렛츠런플레이 상품 상세 안내를 확인해 주세요.',...JSON.parse(localStorage.goodsSettings||'{}')};
const now=Date.now();
let orderData=JSON.parse(localStorage.goodsOrders||'null')||[{number:'G-260918-0003',name:'김말마',phone:'010-0000-0000',address:'경기도 과천시 경마공원대로 107, 1층 수령처',request:'배송 전 연락 부탁드립니다.',createdAt:now,items:[{id:1,name:'말마 인형',qty:2,price:29000},{id:2,name:'경주마 인형 A',qty:1,price:26000}],subtotal:84000,shippingFee:3000,total:87000,status:'출고 대기',inventoryApplied:false},{number:'G-260911-0002',name:'박프렌즈',phone:'010-0000-0000',address:'서울특별시 중구 세종대로 110, 수령처',createdAt:now-7*86400000,items:[{id:2,name:'경주마 인형 A',qty:2,price:26000}],subtotal:52000,shippingFee:3000,total:55000,status:'출고 완료',carrier:'CJ대한통운',trackingNumber:'000000000000',inventoryApplied:false},{number:'G-260908-0001',name:'이경주',phone:'010-0000-0000',address:'부산광역시 강서구 가락대로 929, 수령처',createdAt:now-10*86400000,items:[{id:1,name:'말마 인형',qty:1,price:29000}],subtotal:29000,shippingFee:3000,total:32000,status:'전체 취소',inventoryApplied:false}];
let salesTab='orders',detailOrder=null;
const dateText=o=>o.createdAt?new Date(o.createdAt).toLocaleString('ko-KR'):o.date||'—';
const state=o=>o.status==='출고 대기'?'배송 준비 중':o.status==='출고 완료'?'발송 완료':o.status==='전체 취소'?'취소 완료':o.status;
function persist(){localStorage.goodsOrders=JSON.stringify(orderData);localStorage.goodsProducts=JSON.stringify(goods);localStorage.goodsSettings=JSON.stringify(settings);}
function notify(message){$('adminStatus').textContent=message;}
function filteredOrders(){const keyword=$('keyword').value.trim().toLowerCase(),payment=$('paymentFilter').value,ship=$('shippingFilter').value;return orderData.filter(o=>{const date=o.createdAt?new Date(o.createdAt):null;const day=date?`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`:'';return (salesTab!=='shipping'||o.status==='출고 대기')&&(!keyword||[o.number,o.name,o.phone,o.recipient].join(' ').toLowerCase().includes(keyword))&&(!payment||(payment==='cancelled'?o.status==='전체 취소':o.status!=='전체 취소'))&&(!ship||o.status===ship)&&(!$('startDate').value||day>=$('startDate').value)&&(!$('endDate').value||day<=$('endDate').value);});}
function renderOrders(){const rows=filteredOrders(),shipping=salesTab==='shipping';$('pendingCount').textContent=orderData.filter(o=>o.status==='출고 대기').length;$('resultCount').textContent=rows.length;$('listTitle').firstChild.textContent=shipping?'발송 대기 주문 ':'굿즈 주문 목록 ';$('listHint').textContent=shipping?'발송한 주문을 선택하고 송장번호를 입력해 주세요.':'부분 취소 없이 주문 전체 취소만 가능합니다.';$('shippingToolbar').hidden=!shipping;$('pageCount').textContent=`${rows.length?'1–'+rows.length:'0'} / ${rows.length}건`;
$('ordersTable').innerHTML=rows.length?`<table><thead><tr>${shipping?'<th><input id="allRows" class="ship-check" type="checkbox" aria-label="전체 주문 선택"></th>':''}<th>주문번호</th><th>구매자</th><th>주문상품</th>${shipping?'<th>배송지</th><th>택배사</th><th>송장번호</th>':'<th>결제금액</th><th>결제 · 환불</th><th>배송 상태</th><th>주문일시</th><th>상세</th>'}</tr></thead><tbody>${rows.map(o=>`<tr data-number="${esc(o.number)}">${shipping?'<td><input class="row-check ship-check" type="checkbox" aria-label="'+esc(o.number)+' 선택"></td>':''}<td><b>${esc(o.number)}</b></td><td><b>${esc(o.name)}</b><small>${esc(o.phone)}</small></td><td>${o.items.map(i=>`${esc(i.name)} <b>× ${i.qty}</b>`).join('<br>')}</td>${shipping?`<td>${esc(o.recipient||o.name)}<small>${esc(o.address)}</small><small>${esc(o.request||'')}</small></td><td><select class="carrier-select" aria-label="${esc(o.number)} 택배사"><option value="">기본 택배사</option>${carrierNames.map(c=>`<option ${c===o.carrier?'selected':''}>${c}</option>`).join('')}</select></td><td><input class="tracking-input" inputmode="numeric" aria-label="${esc(o.number)} 송장번호" placeholder="송장번호 입력" value="${esc(o.trackingNumber||'')}"></td>`:`<td><b>${money(o.total)}</b></td><td><span class="badge ${o.status==='전체 취소'?'grey':''}">${o.status==='전체 취소'?'전액 환불 완료':'결제 완료'}</span></td><td><span class="badge ${o.status==='전체 취소'?'grey':o.status==='출고 완료'?'green':''}">${esc(state(o))}</span></td><td>${esc(dateText(o))}</td><td><button data-detail="${esc(o.number)}">상세보기</button></td>`}</tr>`).join('')}</tbody></table>`:'<div class="empty">조건에 맞는 주문이 없습니다.</div>';
$('allRows')?.addEventListener('change',e=>document.querySelectorAll('.row-check').forEach(box=>box.checked=e.target.checked));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>showDetail(b.dataset.detail));}
function showDetail(number){detailOrder=orderData.find(o=>o.number===number);const o=detailOrder;if(!o)return;$('orderDetail').innerHTML=`<p><b>${esc(o.number)}</b> <span class="badge">${esc(state(o))}</span></p><p class="form-note">${esc(dateText(o))}</p><section class="detail-section"><h3>주문상품</h3><div class="detail-box">${o.items.map(i=>`<p class="detail-cost"><span>${esc(i.name)} × ${i.qty}</span><b>${i.price!=null?money(i.price*i.qty):'—'}</b></p>`).join('')}</div></section><section class="detail-section"><h3>회원 · 배송정보</h3><div class="detail-box"><p><b>${esc(o.recipient||o.name)}</b> · ${esc(o.recipientPhone||o.phone)}</p><p>${esc(o.address)} ${esc(o.postcode||'')}</p><p>배송메모: ${esc(o.request||'없음')}</p>${o.trackingNumber?`<p>${esc(o.carrier||'택배사 미등록')} · ${esc(o.trackingNumber)}</p>`:''}</div></section><section class="detail-section"><h3>결제정보</h3><div class="detail-box"><p class="detail-cost"><span>상품금액</span><b>${money(o.subtotal??o.total-(o.shippingFee??settings.shippingFee))}</b></p><p class="detail-cost"><span>배송비</span><b>${money(o.shippingFee??settings.shippingFee)}</b></p><p class="detail-cost total"><span>${o.status==='전체 취소'?'전액 취소금액':'총 결제금액'}</span><b>${money(o.total)}</b></p></div></section><p class="form-note">부분 취소·부분 환불 없이 주문 전체 취소만 가능합니다.</p><div class="dialog-footer"><button data-close="detailDialog">닫기</button>${o.status==='출고 대기'?'<button id="cancelWholeOrder" class="danger">주문 전체 취소</button>':''}</div>`;bindClose();$('cancelWholeOrder')?.addEventListener('click',()=>{if(!confirm('이 주문의 모든 상품을 전액 취소하시겠습니까?'))return;if(o.inventoryApplied!==false)o.items.forEach(i=>{const p=goods.find(p=>p.id===i.id);if(p){p.stock+=i.qty;if(p.status==='soldout')p.status='sale';}});o.status='전체 취소';persist();renderOrders();renderProducts();showDetail(o.number);notify('주문 전체를 취소했습니다.');});if(!$('detailDialog').open)$('detailDialog').showModal();}
$('defaultCarrier').innerHTML=carrierNames.map(c=>`<option ${c===(localStorage.goodsDefaultCarrier||carrierNames[0])?'selected':''}>${c}</option>`).join('');$('defaultCarrier').onchange=()=>localStorage.goodsDefaultCarrier=$('defaultCarrier').value;
$('batchShip').onclick=()=>{const rows=[...document.querySelectorAll('.row-check:checked')].map(c=>c.closest('tr'));if(!rows.length)return notify('발송할 주문을 선택해 주세요.');const updates=rows.map(row=>({order:orderData.find(o=>o.number===row.dataset.number),carrier:row.querySelector('select').value||$('defaultCarrier').value,tracking:row.querySelector('.tracking-input').value.trim().replace(/[\s-]/g,'')}));const bad=updates.find(u=>!/^\d{8,30}$/.test(u.tracking));if(bad)return notify(bad.order.number+'의 송장번호를 숫자 8~30자리로 입력해 주세요.');if(new Set(updates.map(u=>u.carrier+u.tracking)).size!==updates.length||updates.some(u=>orderData.some(o=>o!==u.order&&o.status!=='전체 취소'&&o.carrier===u.carrier&&o.trackingNumber===u.tracking)))return notify('중복된 송장번호를 확인해 주세요.');updates.forEach(u=>Object.assign(u.order,{carrier:u.carrier,trackingNumber:u.tracking,shippedAt:Date.now(),status:'출고 완료'}));persist();renderOrders();notify(updates.length+'건을 발송 완료 처리했습니다.');};
function renderProducts(){const search=$('productSearch').value.trim(),status=$('productStatus').value,rows=goods.filter(p=>(!search||p.name.includes(search))&&(!status||p.status===status));$('productCount').textContent=rows.length;$('feeSummary').textContent=money(settings.shippingFee);$('cancelSummary').textContent='결제 후 '+settings.cancelHours+'시간 이내 · 발송 전';$('productsTable').innerHTML=rows.length?`<table><thead><tr><th>상품</th><th>판매가격</th><th>재고 수량</th><th>판매 상태</th><th>관리</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="product-title"><span class="thumb">${p.image?'<img src="'+esc(p.image)+'" alt="">':esc(p.art||'GOODS')}</span><b>${esc(p.name)}</b></div></td><td><b>${money(p.price)}</b></td><td><b>${p.stock}개</b></td><td><span class="badge ${p.status==='sale'&&p.stock>0?'':'grey'}">${p.status==='hidden'?'판매 중지':p.stock===0||p.status==='soldout'?'품절':'판매 중'}</span></td><td><button data-edit="${p.id}">상품 · 재고 수정</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">조건에 맞는 상품이 없습니다.</div>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(Number(b.dataset.edit)));}
function openEditor(id){const p=goods.find(p=>p.id===id)||{id:'',name:'',price:0,stock:0,image:'',description:'',status:'sale'};$('productEditor').reset();Object.entries(p).forEach(([key,value])=>{if($('productEditor').elements[key])$('productEditor').elements[key].value=value;});DetailEditor.load(p.detailHtml||'');$('productSaveError').textContent='';$('editorTitle').textContent=id?'상품 · 재고 수정':'상품 등록';$('productDialog').showModal();}
$('productEditor').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));f.detailHtml=DetailEditor.value();f.id=Number(f.id)||Date.now();f.price=Number(f.price);f.stock=Number(f.stock);if(!f.stock&&f.status==='sale')f.status='soldout';const previous=goods.map(p=>({...p}));const index=goods.findIndex(p=>p.id===f.id);if(index>=0)goods[index]={...goods[index],...f};else goods.push({...f,art:'GOODS'});try{localStorage.goodsProducts=JSON.stringify(goods);}catch(error){goods=previous;$('productSaveError').textContent='저장 공간이 부족합니다. 이미지 파일을 줄이거나 이미지 URL을 사용한 뒤 다시 저장해 주세요.';return;}$('productDialog').close();renderProducts();notify('상품 정보를 저장했습니다.');};
function openSettings(){Object.entries(settings).forEach(([k,v])=>{if($('settingsForm').elements[k])$('settingsForm').elements[k].value=v;});$('settingsDialog').showModal();}$('openSettings').onclick=openSettings;$('editSettings').onclick=openSettings;$('addGoods').onclick=()=>openEditor();$('settingsForm').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));settings={...settings,...f,shippingFee:Number(f.shippingFee),cancelHours:Number(f.cancelHours)};persist();$('settingsDialog').close();renderProducts();notify('스토어 설정을 저장했습니다. 기존 주문의 금액·취소 기한은 유지됩니다.');};
function bindClose(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=() =>$(b.dataset.close).close());}bindClose();
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));$('salesView').hidden=b.dataset.view!=='sales';$('operationsView').hidden=b.dataset.view!=='operations';document.title=(b.dataset.view==='sales'?'굿즈 판매 현황':'온라인 스토어 운영')+' | 렛츠런파크 관리자';notify('');});document.querySelectorAll('[data-sales-tab]').forEach(b=>b.onclick=()=>{salesTab=b.dataset.salesTab;document.querySelectorAll('[data-sales-tab]').forEach(x=>x.classList.toggle('active',x===b));$('filterForm').reset();renderOrders();notify('');});$('filterForm').onsubmit=e=>{e.preventDefault();renderOrders();};$('resetFilters').onclick=()=>{$('filterForm').reset();renderOrders();};$('productSearch').oninput=renderProducts;$('productStatus').onchange=renderProducts;
$('exportOrders').onclick=()=>{const rows=[['주문번호','구매자','전화번호','상품','수량','수령인','주소','배송메모','결제금액','상태','택배사','송장번호']];filteredOrders().forEach(o=>o.items.forEach(i=>rows.push([o.number,o.name,o.phone,i.name,i.qty,o.recipient||o.name,o.address,o.request||'',o.total,state(o),o.carrier||'',o.trackingNumber||''])));const csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=salesTab==='shipping'?'굿즈_발송대상.csv':'굿즈_주문목록.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
renderOrders();renderProducts();
